"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * CROP GESTURE: a photo you hold, not a box you drag
 *
 *   pan       the photo follows the finger exactly; past an
 *             edge it resists more the further it goes, the way
 *             iOS Photos does, so the crop never shows a gap
 *   pinch     two fingers zoom about the point between them;
 *             wheel and trackpad pinch zoom about the pointer;
 *             below the fit or past the limit it resists too
 *   release   it keeps the speed you let go with and slows
 *             down; anything out of bounds springs back,
 *             critically damped, carrying that speed
 *   rotate    quarter turns, and the bounds re-solve so the
 *             photo still covers the crop
 *
 * One frame loop with fixed 4ms steps, writing transforms to
 * three nested layers (pan, zoom, rotate) and sleeping the
 * moment everything is still. React hears about it once, when
 * it settles. Layers are promoted only while they move, so the
 * photo re-rasterises sharp at its new size.
 * ───────────────────────────────────────────────────────── */

export type CropState = { x: number; y: number; z: number; r: number };
/** The crop in the photo's own pixels: its centre, the side of the square, and the quarter turns applied (degrees). */
export type CropArea = {
  centerX: number;
  centerY: number;
  size: number;
  rotation: number;
};

type Options = {
  /** Side of the crop region at full size, px. */
  size: number;
  /** Natural size of the photo. */
  image: { w: number; h: number } | null;
  maxZoom: number;
  reduced: boolean;
  /** Called once a gesture, wheel, key or spring has settled. */
  onSettle?: (state: CropState) => void;
  refs: {
    pan: React.RefObject<HTMLDivElement | null>;
    zoom: React.RefObject<HTMLDivElement | null>;
    rot: React.RefObject<HTMLDivElement | null>;
    slider: React.RefObject<HTMLInputElement | null>;
    grid: React.RefObject<SVGGElement | null>;
    stage: React.RefObject<HTMLDivElement | null>;
  };
};

import {
  EASE_SETTLE,
  rubberBand,
  softenVelocity,
} from "./imported-ui-interaction-motion";

type Vec = { x: number; y: number };

const K = 260; // spring stiffness, 1/s²
const C = 2 * 0.76 * Math.sqrt(K); // organic damping (zeta ~0.76 with 3% settling breath)
const FRICTION = 4.2; // momentum decay, 1/s
const STEP = 4; // ms
const THROW = EASE_SETTLE;

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));
/** Resistance past an edge: the further over, the less it gives (iOS's 0.55 constant). */
const band = (over: number, dim: number) => rubberBand(over, dim, 0.55);
/** The raw overshoot that shows as `shown` once banded, so a gesture can start from a photo that's mid-spring. */
const unband = (shown: number, dim: number) => {
  const u = Math.min(0.95, Math.abs(shown) / dim);
  return Math.sign(shown) * (1 / (1 - u) - 1) * (dim / 0.55);
};

export function useCropGesture(o: Options) {
  const opts = React.useRef(o);
  React.useLayoutEffect(() => {
    opts.current = o;
  });

  const state = React.useRef<CropState>({ x: 0, y: 0, z: 1, r: 0 });
  const vel = React.useRef({ x: 0, y: 0, z: 0 });
  const goal = React.useRef<Partial<CropState> | null>(null);
  const loop = React.useRef(0);
  const lastFrame = React.useRef(0);
  const pointers = React.useRef(new Map<number, Vec>());
  const hold = React.useRef<{
    x: number;
    y: number;
    z: number;
    mid: Vec;
    dist: number;
  } | null>(null);
  const samples = React.useRef<{ x: number; y: number; t: number }[]>([]);
  const wheelTimer = React.useRef(0);

  /** How far the photo may move each way at zoom z and rotation r before it would uncover the crop. */
  const limits = (z: number, r: number): Vec => {
    const { image: img, size: d } = opts.current;
    if (!img) return { x: 0, y: 0 };
    const cover = d / Math.min(img.w, img.h);
    const w = (r % 2 ? img.h : img.w) * cover * z;
    const h = (r % 2 ? img.w : img.h) * cover * z;
    return { x: Math.max(0, (w - d) / 2), y: Math.max(0, (h - d) / 2) };
  };

  const promote = (on: boolean) => {
    for (const el of [
      opts.current.refs.pan.current,
      opts.current.refs.zoom.current,
    ])
      if (el) el.style.willChange = on ? "transform" : "";
    if (opts.current.refs.grid.current)
      opts.current.refs.grid.current.style.opacity =
        on && hold.current ? "1" : "0";
  };

  const write = () => {
    const s = state.current;
    if (opts.current.refs.pan.current)
      opts.current.refs.pan.current.style.transform = `translate3d(${s.x}px, ${s.y}px, 0)`;
    if (opts.current.refs.zoom.current)
      opts.current.refs.zoom.current.style.transform = `scale(${s.z})`;
    const input = opts.current.refs.slider.current;
    if (input && document.activeElement !== input)
      input.value = String(clamp(s.z, 1, opts.current.maxZoom));
  };

  const settle = React.useCallback(() => {
    cancelAnimationFrame(loop.current);
    loop.current = 0;
    vel.current = { x: 0, y: 0, z: 0 };
    goal.current = null;
    promote(false);
    opts.current.onSettle?.({ ...state.current });
  }, []);

  const tick = (now: number) => {
    const dt = Math.min(48, now - (lastFrame.current || now - 16));
    lastFrame.current = now;
    const s = state.current;
    const v = vel.current;
    const { maxZoom: max } = opts.current;
    const steps = Math.max(1, Math.round(dt / STEP));
    const h = dt / steps / 1000;
    for (let i = 0; i < steps; i++) {
      const zTo = clamp(goal.current?.z ?? s.z, 1, max);
      v.z += (-K * (s.z - zTo) - C * v.z) * h;
      s.z += v.z * h;
      const lim = limits(s.z, s.r);
      for (const axis of ["x", "y"] as const) {
        const target = goal.current?.[axis];
        const bound = lim[axis];
        if (target !== undefined || Math.abs(s[axis]) > bound) {
          // A goal (keys, rotation) or out of bounds: spring there, keeping whatever speed it has.
          const to = clamp(target ?? s[axis], -bound, bound);
          v[axis] += (-K * (s[axis] - to) - C * v[axis]) * h;
        } else v[axis] *= Math.exp(-FRICTION * h);
        s[axis] += v[axis] * h;
      }
    }
    write();
    const lim = limits(s.z, s.r);
    const zTo = clamp(goal.current?.z ?? s.z, 1, max);
    const still =
      Math.abs(v.x) < 4 &&
      Math.abs(v.y) < 4 &&
      Math.abs(v.z) < 0.01 &&
      Math.abs(s.z - zTo) < 0.0008 &&
      Math.abs(s.x) <= lim.x + 0.3 &&
      Math.abs(s.y) <= lim.y + 0.3 &&
      (goal.current?.x === undefined ||
        Math.abs(s.x - clamp(goal.current.x, -lim.x, lim.x)) < 0.3) &&
      (goal.current?.y === undefined ||
        Math.abs(s.y - clamp(goal.current.y, -lim.y, lim.y)) < 0.3);
    if (still) {
      s.z = zTo;
      const end = limits(s.z, s.r);
      s.x = clamp(goal.current?.x ?? s.x, -end.x, end.x);
      s.y = clamp(goal.current?.y ?? s.y, -end.y, end.y);
      write();
      settle();
      return;
    }
    loop.current = requestAnimationFrame(tick);
  };

  const run = () => {
    if (opts.current.reduced) {
      // No springs: land where it would have, at once.
      const s = state.current;
      s.z = clamp(goal.current?.z ?? s.z, 1, opts.current.maxZoom);
      const lim = limits(s.z, s.r);
      s.x = clamp(goal.current?.x ?? s.x, -lim.x, lim.x);
      s.y = clamp(goal.current?.y ?? s.y, -lim.y, lim.y);
      write();
      settle();
      return;
    }
    promote(true);
    if (!loop.current) {
      lastFrame.current = 0;
      loop.current = requestAnimationFrame(tick);
    }
  };

  const stop = () => {
    cancelAnimationFrame(loop.current);
    loop.current = 0;
  };

  React.useEffect(() => () => cancelAnimationFrame(loop.current), []);

  // ── Pointers ───────────────────────────────────────────
  const centre = (p: Vec): Vec => {
    const r = opts.current.refs.stage.current!.getBoundingClientRect();
    return { x: p.x - (r.left + r.width / 2), y: p.y - (r.top + r.height / 2) };
  };
  const midpoint = (): { mid: Vec; dist: number } => {
    const ps = [...pointers.current.values()];
    if (ps.length < 2) return { mid: centre(ps[0]), dist: 0 };
    return {
      mid: centre({ x: (ps[0].x + ps[1].x) / 2, y: (ps[0].y + ps[1].y) / 2 }),
      dist: Math.hypot(ps[0].x - ps[1].x, ps[0].y - ps[1].y),
    };
  };
  /** Start (or restart, when a finger joins or leaves) from what's shown, unbanded so nothing jumps. */
  const begin = () => {
    const s = state.current;
    const { maxZoom: max } = opts.current;
    const z =
      s.z < 1
        ? 1 - (1 - s.z) / 0.35
        : s.z > max
          ? max + (s.z - max) / 0.3
          : s.z;
    const lim = limits(s.z, s.r);
    const d = opts.current.size;
    const raw = (p: number, bound: number) =>
      Math.abs(p) > bound
        ? Math.sign(p) * bound + unband(p - Math.sign(p) * bound, d)
        : p;
    const { mid, dist } = midpoint();
    hold.current = { x: raw(s.x, lim.x), y: raw(s.y, lim.y), z, mid, dist };
    samples.current = [];
  };

  const follow = () => {
    const g = hold.current;
    if (!g) return;
    const s = state.current;
    const { maxZoom: max, size: d } = opts.current;
    const { mid, dist } = midpoint();
    let z = g.z;
    let x = g.x + (mid.x - g.mid.x);
    let y = g.y + (mid.y - g.mid.y);
    if (pointers.current.size > 1 && g.dist > 0) {
      z = g.z * (dist / g.dist);
      // The point of the photo that was under the fingers stays under them.
      x = mid.x - (g.mid.x - g.x) * (z / g.z);
      y = mid.y - (g.mid.y - g.y) * (z / g.z);
    }
    s.z =
      z < 1
        ? Math.max(0.6, 1 - (1 - z) * 0.35)
        : z > max
          ? max + (z - max) * 0.3
          : z;
    const lim = limits(s.z, s.r);
    s.x =
      Math.abs(x) > lim.x
        ? Math.sign(x) * lim.x + band(x - Math.sign(x) * lim.x, d)
        : x;
    s.y =
      Math.abs(y) > lim.y
        ? Math.sign(y) * lim.y + band(y - Math.sign(y) * lim.y, d)
        : y;
    write();
    const t = performance.now();
    samples.current.push({ x: s.x, y: s.y, t });
    while (samples.current.length > 2 && t - samples.current[0].t > 90)
      samples.current.shift();
  };

  const onPointerDown = (e: React.PointerEvent<HTMLElement>) => {
    if (!opts.current.image || (e.pointerType === "mouse" && e.button !== 0))
      return;
    e.currentTarget.setPointerCapture(e.pointerId);
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    // Catch it mid-flight: whatever was moving stops under the finger.
    stop();
    vel.current = { x: 0, y: 0, z: 0 };
    goal.current = null;
    begin();
    promote(true);
  };
  const onPointerMove = (e: React.PointerEvent<HTMLElement>) => {
    if (!pointers.current.has(e.pointerId)) return;
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    follow();
  };
  const onPointerUp = (e: React.PointerEvent<HTMLElement>) => {
    if (!pointers.current.delete(e.pointerId)) return;
    if (pointers.current.size) return begin();
    const ss = samples.current;
    const first = ss[0];
    const last = ss[ss.length - 1];
    const fresh = last && performance.now() - last.t < 80 && last.t > first.t;
    if (fresh) {
      let vx = ((last.x - first.x) / (last.t - first.t)) * 1000;
      let vy = ((last.y - first.y) / (last.t - first.t)) * 1000;
      const lim = limits(state.current.z, state.current.r);
      if (state.current.x > lim.x && vx > 0) vx = softenVelocity(vx, 0, 8);
      else if (state.current.x < -lim.x && vx < 0)
        vx = softenVelocity(vx, 0, 8);
      if (state.current.y > lim.y && vy > 0) vy = softenVelocity(vy, 0, 8);
      else if (state.current.y < -lim.y && vy < 0)
        vy = softenVelocity(vy, 0, 8);
      vel.current = { x: vx, y: vy, z: 0 };
    } else {
      vel.current = { x: 0, y: 0, z: 0 };
    }
    hold.current = null;
    run();
  };

  // Wheel and trackpad pinch zoom about the pointer. Not passive: the page shouldn't scroll under the photo.
  React.useEffect(() => {
    const el = opts.current.refs.stage.current;
    if (!el) return;
    const onWheel = (e: WheelEvent) => {
      if (!opts.current.image) return;
      e.preventDefault();
      stop();
      const s = state.current;
      const { maxZoom: max } = opts.current;
      const z0 = s.z;
      const z1 = clamp(
        z0 * Math.exp(-e.deltaY * (e.ctrlKey ? 0.012 : 0.0016)),
        1,
        max,
      );
      const p = centre({ x: e.clientX, y: e.clientY });
      const lim = limits(z1, s.r);
      s.x = clamp(p.x - (p.x - s.x) * (z1 / z0), -lim.x, lim.x);
      s.y = clamp(p.y - (p.y - s.y) * (z1 / z0), -lim.y, lim.y);
      s.z = z1;
      promote(true);
      write();
      window.clearTimeout(wheelTimer.current);
      wheelTimer.current = window.setTimeout(settle, 160);
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      el.removeEventListener("wheel", onWheel);
      window.clearTimeout(wheelTimer.current);
    };
  }, [o.image, settle]);

  // ── Commands ───────────────────────────────────────────
  /** Zoom to z about the centre at once (the slider). Call settle() yourself when the slider lets go. */
  const zoomTo = (z: number) => {
    stop();
    const s = state.current;
    const z1 = clamp(z, 1, opts.current.maxZoom);
    const lim = limits(z1, s.r);
    s.x = clamp(s.x * (z1 / s.z), -lim.x, lim.x);
    s.y = clamp(s.y * (z1 / s.z), -lim.y, lim.y);
    s.z = z1;
    promote(true);
    write();
  };

  /** Glide by a step (keys, buttons): the spring takes it there and it settles. */
  const nudge = (dx: number, dy: number) => {
    const s = state.current;
    goal.current = {
      x: (goal.current?.x ?? s.x) + dx,
      y: (goal.current?.y ?? s.y) + dy,
      z: goal.current?.z ?? s.z,
    };
    run();
  };
  const zoomBy = (factor: number) => {
    const s = state.current;
    const z0 = goal.current?.z ?? s.z;
    const z1 = clamp(z0 * factor, 1, opts.current.maxZoom);
    goal.current = {
      x: (goal.current?.x ?? s.x) * (z1 / z0),
      y: (goal.current?.y ?? s.y) * (z1 / z0),
      z: z1,
    };
    run();
  };

  /** A quarter turn clockwise, thrown with a slight overshoot; the photo then springs inside the new bounds. */
  const rotate = () => {
    const s = state.current;
    const from = s.r * 90;
    s.r += 1;
    const el = opts.current.refs.rot.current;
    if (el) {
      el.style.transform = `rotate(${s.r * 90}deg)`;
      if (!opts.current.reduced)
        el.animate(
          [
            { transform: `rotate(${from}deg)` },
            { transform: `rotate(${s.r * 90}deg)` },
          ],
          { duration: 480, easing: THROW },
        );
    }
    goal.current = { x: s.x, y: s.y, z: s.z };
    run();
  };

  /** Back to the fit for a new photo. */
  const reset = () => {
    stop();
    state.current = { x: 0, y: 0, z: 1, r: 0 };
    vel.current = { x: 0, y: 0, z: 0 };
    goal.current = null;
    if (opts.current.refs.rot.current)
      opts.current.refs.rot.current.style.transform = "rotate(0deg)";
    write();
  };

  /** Where the crop sits in the photo's own pixels. */
  const area = (): CropArea | null => {
    const { image: img, size: d } = opts.current;
    if (!img) return null;
    const s = state.current;
    const k = (d / Math.min(img.w, img.h)) * s.z;
    const turn = ((s.r % 4) + 4) % 4;
    const a = (-turn * Math.PI) / 2;
    // The crop's centre relative to the photo's centre, on screen, turned back into the photo's own frame.
    const dx = -s.x;
    const dy = -s.y;
    const ux = (dx * Math.cos(a) - dy * Math.sin(a)) / k;
    const uy = (dx * Math.sin(a) + dy * Math.cos(a)) / k;
    return {
      centerX: img.w / 2 + ux,
      centerY: img.h / 2 + uy,
      size: d / k,
      rotation: turn * 90,
    };
  };

  /** Draws the crop into a square canvas of `output` px and encodes it. */
  const toBlob = async (
    img: HTMLImageElement,
    output: number,
    type: string,
    quality: number,
  ): Promise<Blob> => {
    const { image: dims, size: d } = opts.current;
    if (!dims) throw new Error("No photo");
    const s = state.current;
    const canvas = document.createElement("canvas");
    canvas.width = output;
    canvas.height = output;
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("No canvas");
    const k = (d / Math.min(dims.w, dims.h)) * s.z;
    ctx.imageSmoothingQuality = "high";
    ctx.translate(output / 2, output / 2);
    ctx.scale(output / d, output / d);
    ctx.translate(s.x, s.y);
    ctx.rotate((s.r * Math.PI) / 2);
    ctx.scale(k, k);
    ctx.drawImage(img, -dims.w / 2, -dims.h / 2, dims.w, dims.h);
    return new Promise((resolve, reject) =>
      canvas.toBlob(
        (b) =>
          b ? resolve(b) : reject(new Error("Couldn't encode the photo")),
        type,
        quality,
      ),
    );
  };

  return {
    handlers: {
      onPointerDown,
      onPointerMove,
      onPointerUp,
      onPointerCancel: onPointerUp,
    },
    state: () => ({ ...state.current }),
    zoomTo,
    settle,
    nudge,
    zoomBy,
    rotate,
    reset,
    area,
    toBlob,
  };
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

